H.background();
// Polarization — Malus's law:  I = I0 * cos^2(theta)
// theta is the angle between the light's polarization and the analyzer axis.
const cx = H.W * 0.32, cy = H.H * 0.55, R = Math.min(H.W, H.H) * 0.26;
const I0 = P.I0;                 // incident intensity (W/m^2)
const phi = P.phi * Math.PI / 180; // analyzer axis angle (degrees) -> rad
// The incoming light's polarization vector rotates with t (e.g. light through
// a rotating source); the analyzer stays fixed at angle phi.
const psi = (t * 0.6) % (2 * Math.PI);      // incident polarization angle
const theta = psi - phi;                     // angle between them
const I = I0 * Math.cos(theta) * Math.cos(theta);
// Draw the analyzer disk + its transmission axis (fixed).
H.circle(cx, cy, R, { stroke: H.colors.grid, width: 2 });
H.line(cx - R * Math.cos(phi), cy + R * Math.sin(phi), cx + R * Math.cos(phi), cy - R * Math.sin(phi), { color: H.colors.violet, width: 3 });
// Incident polarization vector (rotating).
H.arrow(cx, cy, cx + R * Math.cos(psi), cy - R * Math.sin(psi), { color: H.colors.accent, width: 3 });
// Component that passes = projection onto the analyzer axis.
const proj = Math.cos(theta);
const px = cx + R * proj * Math.cos(phi), py = cy - R * proj * Math.sin(phi);
H.arrow(cx, cy, px, py, { color: H.colors.good, width: 3 });
H.line(cx + R * Math.cos(psi), cy - R * Math.sin(psi), px, py, { color: H.colors.sub, width: 1, dash: [4, 4] });
// Transmitted-intensity bar on the right.
const bx = H.W * 0.72, bw = 50, bh = R * 1.6, by = cy + bh / 2;
H.rect(bx, by - bh, bw, bh, { stroke: H.colors.grid, width: 1.5 });
const frac = (I0 > 1e-9 ? I / I0 : 0);
H.rect(bx, by - bh * frac, bw, bh * frac, { fill: H.colors.good });
H.text("I", bx + bw + 8, by - bh, { color: H.colors.sub, size: 13 });
H.text("Malus's law:  I = I₀·cos²θ", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("I₀=" + I0.toFixed(1) + " W/m²   θ=" + (theta * 180 / Math.PI).toFixed(0) + "°   →   I=" + I.toFixed(2) + " W/m²  (" + (frac * 100).toFixed(0) + "%)", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "incident E", color: H.colors.accent }, { label: "analyzer axis", color: H.colors.violet }, { label: "transmitted", color: H.colors.good }], H.W - 200, 90);
